import { Flow, wfa } from '@servicenow/sdk/automation'
import { trigger } from '@servicenow/sdk/automation'

// Simple Flow with a single Record Trigger and no additional logic instances.

Flow(
    {
        $id: Now.ID['flow_simple'],
        name: 'Simple Flow Example',
        description: 'Demonstrates a basic Flow definition with one trigger and no logic.',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'LOW',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['trigger_simple'], annotation: 'Trigger when incident is created' },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_trigger) => {
        // no-op body
    }
)
